using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatClientBuilder =>
    chatClientBuilder
        .UseFunctionInvocation()
        .Use(new OpenAIClient(
                builder.Configuration["AI:ApiKey"]
                    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
                    ?? throw new InvalidOperationException(
                        "Set AI:ApiKey in config or OPENAI_API_KEY environment variable"))
            .GetChatClient(builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18")
            .AsIChatClient()));

builder.Services.AddSingleton<ResearchNotes>();
builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    "You are a research assistant. When given a topic, use the web_search tool to find "
    + "relevant information from multiple angles. Use the take_note tool to record key "
    + "findings as you go. After gathering enough information (at least 3 searches), "
    + "provide a comprehensive summary of your findings based on your notes.");

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ModelOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [.. AIFunctionFactory.Create(researchTools)],
    },
};

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

var notes = host.Services.GetRequiredService<ResearchNotes>();
if (notes.Notes.Count > 0)
{
    Console.WriteLine("\n--- Research Notes ---");
    foreach (var note in notes.Notes)
    {
        Console.WriteLine($"• {note}");
    }
}

/// <summary>Stores notes collected during research.</summary>
public class ResearchNotes
{
    public List<string> Notes { get; } = [];
}

/// <summary>Tools available to the research agent.</summary>
public class ResearchTools(ResearchNotes notes)
{
    [Description("Search the web for information on a query. Returns relevant search results.")]
    public string web_search([Description("The search query")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (e.g., Bing Search, Google Custom Search).
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        return $"""
            Search results for "{query}":
            1. According to recent articles, {query} is a rapidly evolving area with significant developments in 2025-2026.
            2. Experts note that {query} has implications across multiple industries including technology, healthcare, and finance.
            3. Recent studies show growing investment and research activity in {query}, with major organizations publishing new findings.
            4. Community discussions highlight both opportunities and challenges related to {query}.
            """;
    }

    [Description("Take a note to record an important finding during research.")]
    public string take_note(
        [Description("The content of the note to save")] string content)
    {
        notes.Notes.Add(content);
        Console.WriteLine($"  [Tool] Note saved: \"{content[..Math.Min(content.Length, 60)]}...\"");
        return $"Note saved successfully. Total notes: {notes.Notes.Count}";
    }
}

