using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in config or OPENAI_API_KEY environment variable");

var modelId = builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(sp =>
    new OpenAIClient(apiKey)
        .GetChatClient(modelId)
        .AsIChatClient());

builder.Services.AddSingleton<ResearchNotes>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notes = host.Services.GetRequiredService<ResearchNotes>();

var tools = new AITool[]
{
    AIFunctionFactory.Create((
        [Description("The search query")] string query) =>
    {
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");
        return $"""
            Search results for "{query}":
            1. According to recent articles, {query} is a rapidly evolving area with significant developments in 2025-2026.
            2. Experts note that {query} has implications across multiple industries including technology, healthcare, and finance.
            3. Recent studies show growing investment and research activity in {query}, with major organizations publishing new findings.
            4. Community discussions highlight both opportunities and challenges related to {query}.
            """;
    }, "web_search", "Search the web for information on a query. Returns relevant search results."),

    AIFunctionFactory.Create((
        [Description("The content of the note to save")] string content) =>
    {
